                    if nearest1 is None or d2 < nearest1:
                        nearest1 = d2
                if nearest0 is not None and nearest1 is not None:
                    if nearest0 <= 3:
                        score += (nearest1 - nearest0) * 6.0
                    else:
                        score += (nearest0 - nearest1) * 1.0

